mapper.select:
select order_type, order_no, lot_id, lot_name, pay_amount, pay_status, create_time from ( select 'temp' as order_type, t.order_no, t.lot_id, l.lot_name, t.pay_amount, t.pay_status, t.create_time from parking_temp_order t left join parking_lot l on l.lot_id = t.lot_id and l.del_flag = '0' where t.del_flag = '0'
and t.lot_id in #{id}
union all select 'monthly' as order_type, m.order_no, m.lot_id, l.lot_name, m.pay_amount, m.pay_status, m.create_time from parking_monthly_order m left join parking_lot l on l.lot_id = m.lot_id and l.del_flag = '0' where m.del_flag = '0'
and m.lot_id in #{id}
union all select 'membership' as order_type, mb.order_no, mb.lot_id, l.lot_name, mb.pay_amount, mb.pay_status, mb.create_time from parking_membership_order mb left join parking_lot l on l.lot_id = mb.lot_id and l.del_flag = '0' where mb.del_flag = '0'
and mb.lot_id in #{id}
) recent order by create_time desc limit #{limit}

select
    (select count(1) from parking_lot where del_flag = '0'

       and lot_id in
       #{id}

    ) as lot_count,
    (select count(1) from parking_space where del_flag = '0'

       and lot_id in
       #{id}

    ) as total_space_count,
    (select count(1) from parking_space where del_flag = '0' and status = '0'

       and lot_id in
       #{id}

    ) as available_space_count,
    (select count(1) from parking_space where del_flag = '0' and status = '1'

       and lot_id in
       #{id}

    ) as occupied_space_count,
    (select count(1) from parking_space where del_flag = '0' and status = '2'

       and lot_id in
       #{id}

    ) as disabled_space_count,
    (select count(1) from parking_space where del_flag = '0' and status = '3'

       and lot_id in
       #{id}

    ) as locked_space_count,
    (select count(1) from parking_temp_order where date(in_time) = CURDATE() and del_flag = '0'

       and lot_id in
       #{id}

    ) as today_entry_count,
    (select count(1) from parking_temp_order where date(out_time) = CURDATE() and del_flag = '0'

       and lot_id in
       #{id}

    ) as today_exit_count,
    (select IFNULL(sum(pay_amount), 0) from parking_payment_record where date(pay_time) = CURDATE() and pay_status = '1'

       and lot_id in
       #{id}

    ) as today_revenue,
    (select count(1) from parking_temp_order where biz_status = '0' and del_flag = '0'

       and lot_id in
       #{id}

    ) as active_temp_order_count
